using System.Drawing;using System.Drawing.Imaging;using System.IO;
namespace CuteMouseEffects{static class DynamicCursorRenderer{public static void WriteBuiltInCursor(string id,string output,EffectTheme theme){using(var bmp=new Bitmap(48,48,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(bmp)){g.Clear(Color.Transparent);CursorShapes.Draw(g,id,new RectangleF(2,2,44,44),theme.Shadow,theme.Primary,theme.Secondary,theme.Glow,theme.Core);}using(var ms=new MemoryStream()){bmp.Save(ms,ImageFormat.Png);byte[] data=ms.ToArray();ushort hx=(ushort)(id=="hand"?19:6),hy=(ushort)(id=="hand"?3:5);using(var f=new FileStream(output,FileMode.Create,FileAccess.Write,FileShare.Read))using(var w=new BinaryWriter(f)){w.Write((ushort)0);w.Write((ushort)2);w.Write((ushort)1);w.Write((byte)48);w.Write((byte)48);w.Write((byte)0);w.Write((byte)0);w.Write(hx);w.Write(hy);w.Write((uint)data.Length);w.Write((uint)22);w.Write(data);}}}}}}
